<?php require __DIR__.'/../includes/bootstrap.php';require_member();$pageTitle='My borrowed books';$basePath='../';$s=$pdo->prepare('SELECT m.id FROM members m WHERE m.user_id=?');$s->execute([current_user()['id']]);$mid=$s->fetchColumn();$s=$pdo->prepare('SELECT l.*,b.title,b.author,b.isbn FROM loans l JOIN books b ON b.id=l.book_id WHERE l.member_id=? ORDER BY l.issue_date DESC');$s->execute([$mid]);$rows=$s->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><h3>My borrowing history</h3><p class="muted">Only the administrator can issue or record the return of books.</p><div class="table-wrap"><table><thead><tr><th>Book</th><th>Issue date</th><th>Due date</th><th>Return date</th><th>Qty</th><th>Overdue / estimate</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $l):$days=$l['status']==='issued'?overdue_days($l['due_date']):0;?><tr><td><b><?=e($l['title'])?></b><small><?=e($l['author'])?> · <?=e($l['isbn'])?></small></td><td><?=e($l['issue_date'])?></td><td><?=e($l['due_date'])?></td><td><?=e($l['return_date']??'—')?></td><td><?=$l['quantity']?></td><td><?=$days?($days.' days · '.money($days*(float)setting($pdo,'fine_per_day',10))):'—'?></td><td><span class="pill <?=$l['status']==='issued'?'warning':'success'?>"><?=$l['status']?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">You do not have any borrowing records yet.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
